type gameRelationshipJoins[Q dialect.Joinable] struct {
	GameServers bob.Mod[Q]
	Logs        bob.Mod[Q]
}

func buildGameRelationshipJoins[Q dialect.Joinable](ctx context.Context, typ string) gameRelationshipJoins[Q] {
	return gameRelationshipJoins[Q]{
		GameServers: gamesJoinGameServers[Q](ctx, typ),
		Logs:        gamesJoinLogs[Q](ctx, typ),
	}
}

func gamesJoin[Q dialect.Joinable](ctx context.Context) joinSet[gameRelationshipJoins[Q]] {
	return joinSet[gameRelationshipJoins[Q]]{
		InnerJoin: buildGameRelationshipJoins[Q](ctx, clause.InnerJoin),
		LeftJoin:  buildGameRelationshipJoins[Q](ctx, clause.LeftJoin),
		RightJoin: buildGameRelationshipJoins[Q](ctx, clause.RightJoin),
	}
}

